/// Why a libcurl multi call failed: the core's kind, or a code only the
/// C API produces.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum MultiError {
    /// The core's.
    Core(MultiErrorKind),
    /// Invalid multi handle
    BadHandle,
    /// Internal error
    InternalError,
    /// Invalid socket argument
    BadSocket,
    /// Unknown option
    UnknownOption,
    /// The easy handle is already added to a multi handle
    AddedAlready,
    /// API function called from within callback
    RecursiveApiCall,
    /// Wakeup is unavailable or failed
    WakeupFailure,
    /// A libcurl function was given a bad argument
    BadFunctionArgument,
}

impl MultiError {
    /// Every code only the shim produces, in the order of their C codes.
    pub(crate) const SHIM_ONLY: &[MultiError] = &[
        MultiError::BadHandle,
        MultiError::InternalError,
        MultiError::BadSocket,
        MultiError::UnknownOption,
        MultiError::AddedAlready,
        MultiError::RecursiveApiCall,
        MultiError::WakeupFailure,
        MultiError::BadFunctionArgument,
    ];

    /// The message, as `curl_multi_strerror` gives it.
    pub(crate) fn message(self) -> &'static str {
        match self {
            MultiError::Core(kind) => kind.message(),
            MultiError::BadHandle => "Invalid multi handle",
            MultiError::InternalError => "Internal error",
            MultiError::BadSocket => "Invalid socket argument",
            MultiError::UnknownOption => "Unknown option",
            MultiError::AddedAlready => "The easy handle is already added to a multi handle",
            MultiError::RecursiveApiCall => "API function called from within callback",
            MultiError::WakeupFailure => "Wakeup is unavailable or failed",
            MultiError::BadFunctionArgument => "A libcurl function was given a bad argument",
        }
    }
}

impl From<MultiErrorKind> for MultiError {
    fn from(kind: MultiErrorKind) -> MultiError {
        MultiError::Core(kind)
    }
}

/// The `CURLMcode` of an error.
pub(crate) fn multi_code(error: impl Into<MultiError>) -> CURLMcode {
    match error.into() {
        MultiError::Core(kind) => match kind {
            MultiErrorKind::BadEasyHandle => CURLM_BAD_EASY_HANDLE,
            MultiErrorKind::OutOfMemory => CURLM_OUT_OF_MEMORY,
            MultiErrorKind::AbortedByCallback => CURLM_ABORTED_BY_CALLBACK,
            MultiErrorKind::UnrecoverablePoll => CURLM_UNRECOVERABLE_POLL,
        },
        MultiError::BadHandle => CURLM_BAD_HANDLE,
        MultiError::InternalError => CURLM_INTERNAL_ERROR,
        MultiError::BadSocket => CURLM_BAD_SOCKET,
        MultiError::UnknownOption => CURLM_UNKNOWN_OPTION,
        MultiError::AddedAlready => CURLM_ADDED_ALREADY,
        MultiError::RecursiveApiCall => CURLM_RECURSIVE_API_CALL,
        MultiError::WakeupFailure => CURLM_WAKEUP_FAILURE,
        MultiError::BadFunctionArgument => CURLM_BAD_FUNCTION_ARGUMENT,
    }
}

/// What `curl_multi_strerror` returns for `code`.
pub(crate) fn multi_strerror(code: CURLMcode) -> &'static CStr {
    match code {
        CURLM_CALL_MULTI_PERFORM => c"Please call curl_multi_perform() soon",
        CURLM_OK => c"No error",
        CURLM_BAD_HANDLE => c"Invalid multi handle",
        CURLM_BAD_EASY_HANDLE => c"Invalid easy handle",
        CURLM_OUT_OF_MEMORY => c"Out of memory",
        CURLM_INTERNAL_ERROR => c"Internal error",
        CURLM_BAD_SOCKET => c"Invalid socket argument",
        CURLM_UNKNOWN_OPTION => c"Unknown option",
        CURLM_ADDED_ALREADY => c"The easy handle is already added to a multi handle",
        CURLM_RECURSIVE_API_CALL => c"API function called from within callback",
        CURLM_WAKEUP_FAILURE => c"Wakeup is unavailable or failed",
        CURLM_BAD_FUNCTION_ARGUMENT => c"A libcurl function was given a bad argument",
        CURLM_ABORTED_BY_CALLBACK => c"Operation was aborted by an application callback",
        CURLM_UNRECOVERABLE_POLL => c"Unrecoverable error in select/poll",
        _ => c"Unknown error",
    }
}

/// Why a libcurl share call failed: the core's share never fails, so
/// every code is the C API's.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ShareError {
    /// Unknown share option
    BadOption,
    /// Share currently in use
    InUse,
    /// Invalid share handle
    Invalid,
    /// Out of memory
    Nomem,
    /// Feature not enabled in this library
    NotBuiltIn,
}

impl ShareError {
    /// Every code only the shim produces, in the order of their C codes.
    pub(crate) const SHIM_ONLY: &[ShareError] = &[
        ShareError::BadOption,
        ShareError::InUse,
        ShareError::Invalid,
        ShareError::Nomem,
        ShareError::NotBuiltIn,
    ];

    /// The message, as `curl_share_strerror` gives it.
    pub(crate) fn message(self) -> &'static str {
        match self {
            ShareError::BadOption => "Unknown share option",
            ShareError::InUse => "Share currently in use",
            ShareError::Invalid => "Invalid share handle",
            ShareError::Nomem => "Out of memory",
            ShareError::NotBuiltIn => "Feature not enabled in this library",
        }
    }
}

/// The `CURLSHcode` of an error.
pub(crate) fn share_code(error: ShareError) -> CURLSHcode {
    match error {
        ShareError::BadOption => CURLSHE_BAD_OPTION,
        ShareError::InUse => CURLSHE_IN_USE,
        ShareError::Invalid => CURLSHE_INVALID,
        ShareError::Nomem => CURLSHE_NOMEM,
        ShareError::NotBuiltIn => CURLSHE_NOT_BUILT_IN,
    }
}

/// What `curl_share_strerror` returns for `code`.
pub(crate) fn share_strerror(code: CURLSHcode) -> &'static CStr {
    match code {
        CURLSHE_OK => c"No error",
        CURLSHE_BAD_OPTION => c"Unknown share option",
        CURLSHE_IN_USE => c"Share currently in use",
        CURLSHE_INVALID => c"Invalid share handle",
        CURLSHE_NOMEM => c"Out of memory",
        CURLSHE_NOT_BUILT_IN => c"Feature not enabled in this library",
        _ => c"CURLSHcode unknown",
    }
}

